import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { LeaderboardData, LeaderboardEntry, Run } from "../../src/types";

export type { LeaderboardData, LeaderboardEntry, Run };

// Generated by `npm --prefix .. run build-data`; read at build time only.
const DATA_FILE = join(process.cwd(), "public", "leaderboard.json");

let cached: LeaderboardData | null = null;

export function getData(): LeaderboardData {
  if (cached) return cached;
  if (!existsSync(DATA_FILE)) {
    throw new Error(`${DATA_FILE} not found. Run "npm run data" in leaderboard/site (or "npm run build-data" in leaderboard/) first.`);
  }
  cached = JSON.parse(readFileSync(DATA_FILE, "utf8")) as LeaderboardData;
  return cached;
}

export function getRun(id: string): Run | undefined {
  return getData().runs.find((r) => r.id === id);
}

export function getEntry(participant: string): LeaderboardEntry | undefined {
  return getData().entries.find((e) => e.participant === participant);
}

export function getBaselineRun(): Run | undefined {
  const b = getData().baseline;
  return b ? getRun(b.runId) : undefined;
}
